package net.civeira.phylax.feature.observe.observedembed.application.visibility;

import lombok.Getter;
import lombok.NonNull;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.common.security.InvocationSource;
import net.civeira.phylax.common.security.OperationContext;
import net.civeira.phylax.feature.observe.observedembed.domain.ObservedEmbed;

@Getter
public class ObservedEmbedAccessibleCheck {

  /**
   * @autogenerated AccessibleCheckGenerator
   */
  @NonNull
  private final OperationContext context;

  /**
   * @autogenerated AccessibleCheckGenerator
   */
  private final ObservedEmbed entity;

  /**
   * @autogenerated AccessibleCheckGenerator
   */
  @NonNull
  private Boolean visible;

  /**
   * @autogenerated AccessibleCheckGenerator
   * @param context
   * @param entity
   */
  public ObservedEmbedAccessibleCheck(final OperationContext context, final ObservedEmbed entity) {
    this.context = context;
    this.entity = entity;
    this.visible = true;
  }

  /**
   * @autogenerated AccessibleCheckGenerator
   * @return
   */
  public Actor getActor() {
    return this.context.getActor();
  }

  /**
   * @autogenerated AccessibleCheckGenerator
   * @return
   */
  public InvocationSource getSource() {
    return this.context.getSource();
  }

  /**
   * @autogenerated AccessibleCheckGenerator
   */
  public void hide() {
    this.visible = false;
  }
}
